// ---- Edit for each brand -------------------------------------------------
const CONFIG = {
  brand: 'Example Co',
  supportEmail: 'support@example.com',
  dispatchTime: '1 to 2 working days',   // how long before an order ships
  replyWindow: 'one working day',        // what a person can actually keep to
  signOff: 'The Example Co team',
  maxMessageChars: 1000,
  maxMessagesPerHour: 30,
  ownDomains: ['example.com']           // never answer your own team
};
// --------------------------------------------------------------------------

// Drop anything that is not a customer writing in: auto-replies, bounces,
// newsletters, notifications and our own team. These must never reach the
// model, or they become a bill and a draft nobody wants.
const SKIP_SENDER = /(^|[._-])(no-?reply|do-?not-?reply|mailer-daemon|postmaster|bounces?|notifications?)([._+-]|@)/i;

// Email and order number can arrive in a later message than the question, so
// look across everything the customer has typed, most recent mention first.
const lastMatch = (text, re) => { const all = [...text.matchAll(re)]; return all.length ? all[all.length - 1] : null; };
const findEmail = text => (lastMatch(text, /[^\s@<>()"',;:]+@[^\s@<>()"',;:]+\.[a-z]{2,}/gi)?.[0] ?? '').toLowerCase();
const findOrder = text => lastMatch(text, /#\s?(\d{3,10})\b/g)?.[1]
  ?? lastMatch(text, /\border\s*(?:number|no\.?|num)?\s*[:#]?\s*(\d{3,10})\b/gi)?.[1] ?? '';

const out = [];
for (const item of $input.all()) {
  const m = item.json;
  const from = m.from?.value?.[0] ?? {};
  const email = String(from.address ?? '').trim().toLowerCase();
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) continue;
  if (SKIP_SENDER.test(email)) continue;
  if (CONFIG.ownDomains.some(d => email.endsWith('@' + d.toLowerCase()))) continue;
  const headers = m.headers ?? {};
  const header = k => String(headers[k] ?? '').toLowerCase();
  if (header('list-unsubscribe') || header('list-id')) continue;              // newsletters
  if (/^auto-submitted:\s*(?!no\b)\S/.test(header('auto-submitted'))) continue; // auto-replies
  if (/precedence:\s*(bulk|list|junk)/.test(header('precedence'))) continue;

  // Keep only what the customer wrote this time, not the quoted thread below it.
  const body = String(m.text ?? '')
    .split(/\r?\n(?:On .{0,200}wrote:|-{2,}\s*Original Message|From: .+)\r?\n/i)[0]
    .split(/\r?\n/).filter(l => !l.startsWith('>')).join('\n')
    .trim().slice(0, 4000);
  if (!body) continue;
  const subject = String(m.subject ?? '').trim().slice(0, 200);

  out.push({ json: {
    config: CONFIG,
    channel: 'email',
    thread: m.threadId ?? '',
    gmailId: m.id ?? '',
    subject,
    firstName: String(from.name ?? '').trim().split(/\s+/)[0] ?? '',
    message: `${subject}\n\n${body}`,
    history: [],
    email,                                    // the sender is the customer
    orderNumber: findOrder(`${subject}\n${body}`),
    route: '',
    reply: '',
    receivedAt: new Date().toISOString()
  } });
}
return out;

// The FAQ sheet is the whole of what the assistant knows. Rows missing a
// question or an answer are skipped rather than half-used.
const rows = $input.all().map(i => i.json)
  .filter(r => String(r.question ?? '').trim() && String(r.answer ?? '').trim());
const faq = rows.slice(0, 150).map((r, n) =>
  `Q${n + 1}: ${String(r.question).trim()}\nA: ${String(r.answer).trim()}` +
  (String(r.link ?? '').trim() ? `\nLink: ${String(r.link).trim()}` : '')
).join('\n\n') || '(The FAQ is empty. Treat every question as "human".)';

return $('Settings and clean input').all()
  .filter(item => item.json.route !== 'blocked')
  .map(item => {
    const c = item.json;
    const earlier = c.history.map(t => `${t.role === 'user' ? 'Customer' : 'Assistant'}: ${t.text}`).join('\n');
    return { json: { ...c, faq, prompt:
      (earlier ? `Earlier in this conversation:\n${earlier}\n\n` : '') +
      `Latest message from the customer:\n${c.message}` } };
  });

// Turn the model's verdict into a route and a reply. The model only picks
// the intent and words FAQ answers. Every promise, every request for missing
// details and every handoff message is written here in code, so a model
// cannot promise a refund, a date, or an address change.
const INTENTS = ['faq', 'order_status', 'order_problem', 'address_change', 'human', 'off_topic'];
const reachYou = c => c.channel === 'ghl'
  ? `someone will reply here within ${c.config.replyWindow}`
  : `they'll email you at ${c.email} within ${c.config.replyWindow}`;
const ctx = $('Build prompt').all();
const out = [];
$input.all().forEach((item, i) => {
  if (!ctx[i]) return;
  const { faq, prompt, ...c } = ctx[i].json;
  const cfg = c.config;

  let v = null;
  try {
    const raw = item.json.message?.content ?? item.json.content;
    v = typeof raw === 'string' ? JSON.parse(raw) : raw;
  } catch (e) { /* v stays null and is handled as "human" below */ }
  let intent = String(v?.intent ?? '').trim().toLowerCase();
  if (!INTENTS.includes(intent)) intent = 'human';     // outage, bad JSON, invented label: a person looks
  const answer = String(v?.answer ?? '').trim().slice(0, 900);
  if (intent === 'faq' && !answer) intent = 'human';
  const summary = String(v?.summary ?? '').trim().slice(0, 200) || (v ? '' : 'assistant unavailable');

  const isEmail = c.channel === 'email';
  const answered = isEmail ? 'draft' : 'reply';
  const forOrder = c.orderNumber ? ` for order #${c.orderNumber}` : '';
  let route, reply = '';

  if (intent === 'faq') {
    route = answered;
    reply = answer;
  } else if (intent === 'off_topic') {
    route = isEmail ? 'skip' : 'reply';
    reply = `I can help with orders, delivery, returns and product questions for ${cfg.brand}. For anything else, email ${cfg.supportEmail}.`;
  } else if (intent === 'order_status') {
    const missing = [
      !c.orderNumber && 'your order number (it is in your confirmation email, for example #1234)',
      !c.email && 'the email address you ordered with'
    ].filter(Boolean);
    if (missing.length) { route = answered; reply = `Happy to check. Could you send me ${missing.join(' and ')}?`; }
    else route = 'lookup';
  } else if (!c.email && c.channel === 'website') {
    // order_problem, address_change and human always go to a person, who needs
    // a way back to the customer. Email and GHL already have one; the website does not.
    route = answered;
    reply = `I'll pass this to the team. What's the best email address to reach you on?`;
  } else {
    route = 'handoff';
    reply = intent === 'address_change'
      ? `I can't change an address myself, but I've sent your request${forOrder} to the team, and ${reachYou(c)}. If the order has already shipped, they'll tell you what's still possible.`
      : intent === 'order_problem'
      ? `I'm sorry about that. I've passed this${forOrder} to the team and ${reachYou(c)}. If anything arrived damaged, photos help them sort it faster.`
      : `I've passed this to the team and ${reachYou(c)}.`;
  }

  if (isEmail && route === 'draft') reply = `Hi ${c.firstName || 'there'},\n\n${reply}\n\n${cfg.signOff}`;
  const transcript = [...c.history.filter(t => t.role === 'user').map(t => t.text), c.message].join('\n---\n').slice(0, 3000);
  out.push({ json: { ...c, intent, summary, route, reply, transcript } });
});
return out;

// Only say anything about an order when BOTH the order number and the email
// match the same order. A wrong guess gets the same answer as a typo, so
// nobody can fish for someone else's order details.
const fmt = d => d ? new Date(d).toLocaleDateString('en-GB', { day: 'numeric', month: 'long' }) : '';
const digits = s => String(s ?? '').replace(/\D/g, '');
const out = [];
$input.all().forEach((item, i) => {
  const c = $('Decide route').itemMatching(i).json;
  const cfg = c.config;
  const isEmail = c.channel === 'email';
  const answered = isEmail ? 'draft' : 'reply';
  const n = c.orderNumber;
  const r = item.json;
  let route = answered, reply, lookup;

  if (r.error || !Array.isArray(r.orders)) {
    lookup = 'failed';
    route = 'handoff';
    reply = `I can't reach the order system right now, so I've passed this to the team, and ${c.channel === 'ghl' ? `someone will reply here within ${cfg.replyWindow}` : `they'll email you at ${c.email} within ${cfg.replyWindow}`}.`;
  } else {
    const o = r.orders.find(o => digits(o.name) === n &&
      [o.email, o.contact_email, o.customer?.email].some(e => String(e ?? '').trim().toLowerCase() === c.email));
    if (!o) {
      lookup = 'not_found';
      reply = `I couldn't find an order matching #${n} and ${c.email}. Could you double-check both? The order number is in your confirmation email.`;
    } else if (o.cancelled_at) {
      lookup = 'found';
      reply = `Order #${n} was cancelled on ${fmt(o.cancelled_at)}. If that's unexpected, reply here and I'll pass it to the team.`;
    } else if (!o.fulfillment_status || o.fulfillment_status === 'unfulfilled') {
      lookup = 'found';
      reply = `Order #${n} is being packed and hasn't shipped yet. Orders usually leave us within ${cfg.dispatchTime}, and you'll get a tracking email as soon as it does.`;
    } else {
      lookup = 'found';
      const shipped = (o.fulfillments ?? []).filter(f => f.status !== 'cancelled' && f.status !== 'failure');
      const last = shipped[shipped.length - 1];
      const links = [...new Set(shipped.flatMap(f => f.tracking_urls?.length ? f.tracking_urls : (f.tracking_url ? [f.tracking_url] : [])))].slice(0, 3);
      const partial = o.fulfillment_status === 'partial';
      const what = partial ? `Part of order #${n}` : `Order #${n}`;
      reply = (last?.created_at ? `${what} shipped on ${fmt(last.created_at)}` : `${what} has shipped`) +
        `${last?.tracking_company ? ` with ${last.tracking_company}` : ''}. ` +
        (links.length ? `You can track it here: ${links.join(' ')}` : `The tracking details are in your shipping confirmation email.`) +
        (partial ? ` The rest will follow in a separate parcel.` : '');
    }
  }
  if (isEmail && route === 'draft') reply = `Hi ${c.firstName || 'there'},\n\n${reply}\n\n${cfg.signOff}`;
  out.push({ json: { ...c, route, reply, lookup } });
});
return out;

